      "owner": "developer",
      "requirement_ids": [
        "R7",
        "R8"
      ],
      "depends_on": [
        "T1"
      ]
    },
    {
      "id": "T3",
      "title": "Implement UrlSecurityValidator with scheme validation, recursive DNS/SSRF IP checks, and domain denylist filtering",
      "owner": "developer",
      "requirement_ids": [
        "R1",
